          // PROXY-protocol → реальный IP клиента в nginx
          "serverNames": [
            "your.domain"
          ],
          // ← ВАШ домен (A-запись на эту ноду)
          "privateKey": "PRIVATE_KEY_X25519",
          // ← privateKey из генератора панели
