#!/usr/bin/env bash
# gen-cascade.sh — генератор каскада: РФ-вход -> загран-выход (VLESS+TLS+gRPC хоп).
set -euo pipefail

echo "=== Генератор каскада: РФ-вход -> загран-выход ==="
read -rp "IP или домен ВЫХОДНОГО (загран) сервера: " EXIT_HOST
[ -z "${EXIT_HOST:-}" ] && { echo "нужен адрес выхода"; exit 1; }
read -rp "Порт хопа вход->выход [2053]: " HOP; HOP=${HOP:-2053}
read -rp "Имя gRPC-сервиса [grpccascade]: " SVC; SVC=${SVC:-grpccascade}

XRAY=$(command -v xray 2>/dev/null || echo /tmp/xray)
if ! "$XRAY" version >/dev/null 2>&1; then
 command -v unzip >/dev/null 2>&1 || { apt-get update -y >/dev/null 2>&1; apt-get install -y unzip >/dev/null 2>&1; }
 U=$(curl -fsSL https://api.github.com/repos/XTLS/Xray-core/releases/latest | grep -oE 'https://[^"]*Xray-linux-64\.zip' | head -1)
 curl -fsSL -o /tmp/xray.zip "$U" && unzip -o /tmp/xray.zip xray -d /tmp >/dev/null && chmod +x /tmp/xray; XRAY=/tmp/xray
fi
BRIDGE=$("$XRAY" uuid)

OUT=${OUT_DIR:-/root/cascade}; mkdir -p "$OUT"
# самоподписанный серт для хопа (аутентификация — по bridge-UUID, серт лишь шифрует канал)
openssl req -x509 -newkey rsa:2048 -nodes -days 3650 \
 -subj "/CN=$EXIT_HOST" -keyout "$OUT/hop-key.pem" -out "$OUT/hop-cert.pem" >/dev/null 2>&1
# xray 26 убрал allowInsecure -> pinnedPeerCertSha256 = HEX SHA256 серта (строкой)
PIN=$(openssl x509 -in "$OUT/hop-cert.pem" -noout -fingerprint -sha256 | sed 's/.*=//; s/://g' | tr 'A-F' 'a-f')

# === ВЕСЬ КОНФИГ ВЫХОДНОГО (загран) СЕРВЕРА ===
cat >"$OUT/cascade-exit.json" <<JSON
{
 "inbounds": [{
 "tag": "hop-in",
 "listen": "0.0.0.0",
 "port": $HOP,
 "protocol": "vless",
 "settings": { "clients": [{ "id": "$BRIDGE" }], "decryption": "none" },
 "streamSettings": {
 "network": "grpc",
 "security": "tls",
 "grpcSettings": { "serviceName": "$SVC" },
 "tlsSettings": { "certificates": [{ "certificateFile": "$OUT/hop-cert.pem", "keyFile": "$OUT/hop-key.pem" }] }
 }
 }],
 "outbounds": [{ "protocol": "freedom", "tag": "direct" }]
}

